const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map() // key -> {col,row,key,content}
for (let i = 0; i < lines.length; i++) {
  let s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const raw = m[0]
  const a = parseAddr(raw)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  if (cells.has(a.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.key} is declared twice\n`)
    process.exit(2)
  }
  const content = s.slice(raw.length).replace(/^[ \t]+/, '')
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content })
}
const order = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)

// ---- formula parser
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) { toks.push({ k: 'num', v: m[0] }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(src.slice(i)))) { toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
  const fail = () => { throw new Error('g') }
  function cmp() {
    let l = add()
    while (peek() && peek().k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { type: 'neg', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.k === 'num') { p++; return { type: 'num', v: Number(t.v) } }
    if (isOp('(')) {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { type: 'paren', e }
    }
    if (t.k === 'word') {
      p++
      const up = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        const args = []
        if (!isOp(')')) {
          args.push(cmp())
          while (isOp(',')) { p++; args.push(cmp()) }
        }
        if (!isOp(')')) fail()
        p++
        return { type: 'call', name: up, args }
      }
      if (up === 'TRUE') return { type: 'bool', v: true }
      if (up === 'FALSE') return { type: 'bool', v: false }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') fail()
        p++
        const u2 = t2.v.toUpperCase()
        if (isOp('(') || u2 === 'TRUE' || u2 === 'FALSE') fail()
        return { type: 'range', a: t.v, b: t2.v }
      }
      return { type: 'ref', a: t.v }
    }
    fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e.message === 'g') return null
    throw e
  }
}

// static: misplaced range check
function misplaced(n, direct) {
  switch (n.type) {
    case 'range': return !direct
    case 'bin': return misplaced(n.l, false) || misplaced(n.r, false)
    case 'neg': case 'paren': return misplaced(n.e, false)
    case 'call': return n.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function walkDeps(n, out) {
  switch (n.type) {
    case 'ref': { const a = parseAddr(n.a); if (a) out.set(a.key, a); break }
    case 'range': {
      const a = parseAddr(n.a), b = parseAddr(n.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
            const k = colName(c) + r
            out.set(k, { col: c, row: r, key: k })
          }
      }
      break
    }
    case 'bin': walkDeps(n.l, out); walkDeps(n.r, out); break
    case 'neg': case 'paren': walkDeps(n.e, out); break
    case 'call': n.args.forEach((x) => walkDeps(x, out)); break
  }
}
function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const x = c - 27
  return String.fromCharCode(65 + Math.floor(x / 26)) + String.fromCharCode(65 + (x % 26))
}

// ---- evaluation
const parsed = new Map()
function formulaOf(cell) {
  if (!parsed.has(cell.key)) {
    const ast = cell.content[0] === '=' ? parseFormula(cell.content.slice(1)) : null
    parsed.set(cell.key, ast)
  }
  return parsed.get(cell.key)
}

const memo = new Map()
const busy = new Set()

function cellValue(key) {
  const cell = cells.get(key)
  if (!cell) return num(0)
  if (memo.has(key)) return memo.get(key)
  if (busy.has(key)) return err('#CYCLE!')
  busy.add(key)
  let v
  const c = cell.content
  if (c[0] === '=') {
    const ast = formulaOf(cell)
    if (!ast || misplaced(ast, false)) v = err('#ERR!')
    else v = evalNode(ast)
  } else if (c === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) v = num(Number(c))
  else if (ERRS.includes(c)) v = err(c)
  else v = { t: 's', v: c }
  busy.delete(key)
  memo.set(key, v)
  return v
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
function fin(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }

function cpCmp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] < rank[b.t] ? -1 : 1
  if (a.t === 's') return cpCmp(a.v, b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function rangeValues(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return [err('#REF!')]
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(colName(c) + r))
  return out
}

function evalNode(n) {
  switch (n.type) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'b', v: n.v }
    case 'paren': return evalNode(n.e)
    case 'ref': {
      const a = parseAddr(n.a)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'neg': {
      const v = evalNode(n.e)
      if (v.t === 'e') return v
      const x = toNum(v)
      if (x.t === 'e') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l.t === 'e') return l
      if (r.t === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { t: 'b', v: res }
      }
      const x = toNum(l), y = toNum(r)
      if (x.t === 'e') return x
      if (y.t === 'e') return y
      switch (n.op) {
        case '+': return fin(x.v + y.v)
        case '-': return fin(x.v - y.v)
        case '*': return fin(x.v * y.v)
        case '/': return y.v === 0 ? err('#DIV/0!') : fin(x.v / y.v)
        case '^': return fin(Math.pow(x.v, y.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = evalNode(args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return evalNode(truth ? args[1] : args[2])
  }
  if (name === 'ABS' ? args.length !== 1 : args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.type === 'range') vals.push(...rangeValues(a))
    else vals.push(evalNode(a))
  }
  const e = vals.find((v) => v.t === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'ABS': return num(Math.abs(nums[0]))
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s), Infinity))
    case 'MAX': return num(nums.reduce((s, x) => (x > s ? x : s), -Infinity))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
  return err('#ERR!')
}

function fmt(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const out = []
for (const cell of order) {
  if (mode === 'values') out.push(`${cell.key}=${fmt(cellValue(cell.key))}`)
  else {
    let line = cell.key + ':'
    if (cell.content[0] === '=') {
      const ast = formulaOf(cell)
      if (ast) {
        const m = new Map()
        walkDeps(ast, m)
        const ds = [...m.values()].sort((x, y) => x.col - y.col || x.row - y.row)
        for (const d of ds) line += ' ' + d.key
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
